/*
 * Colormaps as 256-entry RGB lookup tables, base64-encoded (768 bytes each).
 * Generated with matplotlib:
 *     (colormaps[name](linspace(0,1,256))[:, :3] * 255).round().astype(uint8)
 * Applied in the browser so the server never handles colour and the same
 * grayscale raster can be re-coloured instantly.
 */
(function (global) {
  'use strict';

  var B64 = {
    turbo: '',
    viridis: '',
  };

  function decode(b64) {
    var raw = atob(b64);
    var lut = new Uint8Array(768);
    for (var i = 0; i < 768; i++) lut[i] = raw.charCodeAt(i);
    return lut;
  }

  var luts = {};
  Object.keys(B64).forEach(function (k) { luts[k] = decode(B64[k]); });

  // grayscale is the identity map
  (function () {
    var g = new Uint8Array(768);
    for (var i = 0; i < 256; i++) { g[i*3] = i; g[i*3+1] = i; g[i*3+2] = i; }
    luts.gray = g;
  })();

  global.AuroraColormaps = {
    names: Object.keys(luts),
    lut: function (name) { return luts[name] || luts.turbo; },

    /** Fill a canvas with the colour ramp (used for the legend). */
    drawRamp: function (canvas, name) {
      var lut = this.lut(name);
      var ctx = canvas.getContext('2d');
      var w = canvas.width, h = canvas.height;
      var img = ctx.createImageData(w, h);
      for (var x = 0; x < w; x++) {
        var i = Math.round(x / (w - 1) * 255) * 3;
        for (var y = 0; y < h; y++) {
          var o = (y * w + x) * 4;
          img.data[o] = lut[i];
          img.data[o + 1] = lut[i + 1];
          img.data[o + 2] = lut[i + 2];
          img.data[o + 3] = 255;
        }
      }
      ctx.putImageData(img, 0, 0);
    }
  };
})(window);
